(6482280, 963319, 85430, '<td valign="top">Cool. Was the blue color natural or just saturated in PP? Nice image, btw. Simplicity is the beauty in this shot.</td>', 'Cool. Was the blue color natural or just saturated in PP? Nice image, btw. Simplicity is the beauty in this shot.', '2011-07-27 11:41:59.000000', NULL, 1),
(6482284, 963229, 85430, '<td valign="top">Great colors. Excellent focus. What a beauty.</td>', 'Great colors. Excellent focus. What a beauty.', '2011-07-27 11:43:01.000000', NULL, 1),
(6482286, 963084, 85430, '<td valign="top">Great perspective. It seems like direct sunlight on glass surfaces, and yet you managed to handle the exposure really well, avoiding shiny reflections. I like how you framed this shot. Well done.</td>', 'Great perspective. It seems like direct sunlight on glass surfaces, and yet you managed to handle the exposure really well, avoiding shiny reflections. I like how you framed this shot. Well done.', '2011-07-27 11:46:02.000000', NULL, 1),
(6482289, 963411, 85430, '<td valign="top">Amazing shot. Really well planned and executed. The location of adds a lot to this image.</td>', 'Amazing shot. Really well planned and executed. The location of adds a lot to this image.', '2011-07-27 11:48:51.000000', NULL, 1),
(6482290, 963030, 85430, '<td valign="top">I like the dark tone of the image. The focus is great. Great photo.</td>', 'I like the dark tone of the image. The focus is great. Great photo.', '2011-07-27 11:50:54.000000', NULL, 1),
(6482293, 963388, 85430, '<td valign="top">I''d like to use this as a wallpaper on my tablet. Great image</td>', 'I''d like to use this as a wallpaper on my tablet. Great image', '2011-07-27 11:52:47.000000', NULL, 1),
(6482295, 963241, 85430, '<td valign="top">Nice simple image. Is that glass panels on a building? I wish there were clouds in the reflection.</td>', 'Nice simple image. Is that glass panels on a building? I wish there were clouds in the reflection.', '2011-07-27 11:55:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6482297, 963447, 85430, '<td valign="top">Cool red. I''ve seen this somewhere before.</td>', 'Cool red. I''ve seen this somewhere before.', '2011-07-27 11:56:55.000000', NULL, 1),
(6482298, 963413, 85430, '<td valign="top">Great image. What is that? Great lighting, contrast and the black and white.</td>', 'Great image. What is that? Great lighting, contrast and the black and white.', '2011-07-27 11:58:47.000000', NULL, 1),
(6482303, 963008, 85430, '<td valign="top">Great composition. I like how you framed this image. But i think the lighting may have been harsh.</td>', 'Great composition. I like how you framed this image. But i think the lighting may have been harsh.', '2011-07-27 11:59:56.000000', NULL, 1),
(6482307, 963397, 85430, '<td valign="top">Great capture. A tighter crop to remove the foliages on the left would make this image even greater.</td>', 'Great capture. A tighter crop to remove the foliages on the left would make this image even greater.', '2011-07-27 12:01:23.000000', NULL, 1),
(6482309, 962441, 85430, '<td valign="top">Amazing shot. One of my top picks.</td>', 'Amazing shot. One of my top picks.', '2011-07-27 12:01:56.000000', NULL, 1),
(6482314, 963231, 85430, '<td valign="top">The thumbnail makes this photo look like sand dunes. Nice framing. Lighting is a bit strong, but nice image still.</td>', 'The thumbnail makes this photo look like sand dunes. Nice framing. Lighting is a bit strong, but nice image still.', '2011-07-27 12:06:51.000000', NULL, 1),
(6482316, 963284, 85430, '<td valign="top">Great colors. The droplet worked out really well.</td>', 'Great colors. The droplet worked out really well.', '2011-07-27 12:09:05.000000', NULL, 1),
(6482317, 963474, 85430, '<td valign="top">Nice, clean image. Very well executed. The post processing was not overdone. Great shot.</td>', 'Nice, clean image. Very well executed. The post processing was not overdone. Great shot.', '2011-07-27 12:12:00.000000', NULL, 1),
(6482371, 963373, 61396, '<td valign="top">great find. I wonder how would it look in b/w.</td>', 'great find. I wonder how would it look in b/w.', '2011-07-27 14:24:17.000000', NULL, 1),
(6482372, 963330, 61396, '<td valign="top">those toes were playing in the sandbox minutes ago, right? great pattern and a presentation to match.</td>', 'those toes were playing in the sandbox minutes ago, right? great pattern and a presentation to match.', '2011-07-27 14:26:31.000000', NULL, 1),
(6482375, 962870, 103142, '<td valign="top">I hope this is doing well -- when I was going through and voting a couple of days ago, I thought it showed itself quite nicely!</td>', 'I hope this is doing well -- when I was going through and voting a couple of days ago, I thought it showed itself quite nicely!', '2011-07-27 14:28:40.000000', NULL, 1),
(6482376, 963478, 103142, '<td valign="top">This really is pretty cool...</td>', 'This really is pretty cool...', '2011-07-27 14:29:00.000000', NULL, 1),
(6482377, 963361, 61396, '<td valign="top">so at what time do you need to get there in order to be alone? nice presentation.</td>', 'so at what time do you need to get there in order to be alone? nice presentation.', '2011-07-27 14:29:19.000000', NULL, 1),
(6482378, 962430, 103142, '<td valign="top">This is pretty cool! I think I''ve seen it in a photo before, but I don''t remember what it is. I''m curious what it would have looked like  with the sky blown so that it was exposed more for the structure. Doesn''t matter either way, I voted a couple of days ago and voted it quite high. It''s just curiosity. :)</td>', 'This is pretty cool! I think I''ve seen it in a photo before, but I don''t remember what it is. I''m curious what it would have looked like  with the sky blown so that it was exposed more for the structure. Doesn''t matter either way, I voted a couple of days ago and voted it quite high. It''s just curiosity. :)', '2011-07-27 14:30:40.000000', NULL, 1),
(6482379, 963057, 103142, '<td valign="top">I like this quite a bit. I''m glad that you chose B&amp;W for it.</td>', 'I like this quite a bit. I''m glad that you chose B&W for it.', '2011-07-27 14:31:06.000000', NULL, 1),
(6482380, 963411, 103142, '<td valign="top">I''m wondering whether people will think this fits a pattern challenge. But I think it fits wonderfully -- it''s all about the patterns. 8</td>', 'I''m wondering whether people will think this fits a pattern challenge. But I think it fits wonderfully -- it''s all about the patterns. 8', '2011-07-27 14:31:48.000000', NULL, 1),
(6482381, 963388, 103142, '<td valign="top">quite cool! 8</td>', 'quite cool! 8', '2011-07-27 14:31:58.000000', NULL, 1),
(6482382, 963480, 103142, '<td valign="top">Nicely done on the grater shot! 8</td>', 'Nicely done on the grater shot! 8', '2011-07-27 14:32:18.000000', NULL, 1),
(6482384, 962361, 61396, '<td valign="top">The crop and blur make this intriguing image more of a pattern. I wonder what would be the impact of turning this up side down (just wondering, not voting).</td>', 'The crop and blur make this intriguing image more of a pattern. I wonder what would be the impact of turning this up side down (just wondering, not voting).', '2011-07-27 14:36:15.000000', NULL, 1),
(6482400, 963496, 61396, '<td valign="top">I envy you, as I may see a pattern in things, while you show us a (live!) thing made out of a mere pattern.</td>', 'I envy you, as I may see a pattern in things, while you show us a (live!) thing made out of a mere pattern.', '2011-07-27 15:21:38.000000', NULL, 1),
(6482616, 963445, 106484, '<td valign="top">My favourite so far. Very nice!</td>', 'My favourite so far. Very nice!', '2011-07-27 18:47:20.000000', NULL, 1),
(6482618, 963297, 106484, '<td valign="top">Great shot, shame about the out of focus drops at the bottom though. It might have worked better with some of those cropped out.</td>', 'Great shot, shame about the out of focus drops at the bottom though. It might have worked better with some of those cropped out.', '2011-07-27 18:48:16.000000', NULL, 1),
(6482619, 962574, 106484, '<td valign="top">Excellent!</td>', 'Excellent!', '2011-07-27 18:48:30.000000', NULL, 1),
(6482638, 962430, 132996, '<td valign="top">This is intense. It induces such a powerful effect on the viewer''s perception. The feeling of smallness it creates is amazing.</td>', 'This is intense. It induces such a powerful effect on the viewer''s perception. The feeling of smallness it creates is amazing.', '2011-07-27 19:44:23.000000', NULL, 1),
(6482639, 963445, 132996, '<td valign="top">I believe these are leaves? The impression is strong that they''re knives. The strong contrast plays up this illusion.</td>', 'I believe these are leaves? The impression is strong that they''re knives. The strong contrast plays up this illusion.', '2011-07-27 19:46:03.000000', NULL, 1),
(6482641, 963201, 132996, '<td valign="top">Cute way to break the pattern. Such a different element to add, it develops a nice contrast. Wonderful.</td>', 'Cute way to break the pattern. Such a different element to add, it develops a nice contrast. Wonderful.', '2011-07-27 19:48:38.000000', NULL, 1),
(6482643, 962574, 132996, '<td valign="top">Yes. He has the creeper face on.</td>', 'Yes. He has the creeper face on.', '2011-07-27 19:49:43.000000', NULL, 1),
(6482644, 963491, 132996, '<td valign="top">Amazing use of bokeh. It really creates a magical feel. A pastel palette would have aided in that feel.</td>', 'Amazing use of bokeh. It really creates a magical feel. A pastel palette would have aided in that feel.', '2011-07-27 19:50:51.000000', NULL, 1),
(6482647, 963493, 132996, '<td valign="top">I love the soft curves of the leaf and the irregularity of the pattern. I don''t like the bottom left corner though, it''s a bit distracting to me.</td>', 'I love the soft curves of the leaf and the irregularity of the pattern. I don''t like the bottom left corner though, it''s a bit distracting to me.', '2011-07-27 19:52:39.000000', NULL, 1),
(6482651, 963084, 132996, '<td valign="top">Reminds me of Willy Wonka.<br/>I like the reflections in the windows and how you can see the imperfections and glares...wondrous.</td>', 'Reminds me of Willy Wonka.I like the reflections in the windows and how you can see the imperfections and glares...wondrous.', '2011-07-27 19:59:50.000000', NULL, 1),
