(6484238, 963427, 2158, '<td valign="top">Thanks <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=120171" rel="nofollow" target="_blank">Jon_H</a>.  If you think that''s tough, most of the week I wasn''t sure this would even finish above 5.  After 19 votes it was at 4.68.</td>', 'Thanks  Jon_H.  If you think that''s tough, most of the week I wasn''t sure this would even finish above 5.  After 19 votes it was at 4.68.', '2011-07-29 14:51:11.000000', NULL, 0),
(6484310, 963330, 82985, '<td valign="top">The tones, depth, texture, everything is just exactly right.  I gave it a 9 in my first pass vote, and didn''t get back in time for a second pass, when I would have bumped it to a 10.</td>', 'The tones, depth, texture, everything is just exactly right.  I gave it a 9 in my first pass vote, and didn''t get back in time for a second pass, when I would have bumped it to a 10.', '2011-07-29 15:53:58.000000', NULL, 0),
(6484374, 963330, 12611, '<td valign="top">I was drawn to the tones and vignetting, the peripheral vision feeling of not being able to focus on the corners. But when it really opened up, is when I finally let my eyes release focus; the pattern became clear to me...</td>', 'I was drawn to the tones and vignetting, the peripheral vision feeling of not being able to focus on the corners. But when it really opened up, is when I finally let my eyes release focus; the pattern became clear to me...', '2011-07-29 16:23:56.000000', NULL, 0),
